# 3D icons for the Free tools hub cards (same style as the homepage problem icons).
# Key = the card link used in TOOLS in gen_tool_aicost.py. New tool: add an icon here with its own
# gradient id prefix (one letter not used below) and, if you like, a class from the hub CSS
# (t-spin, t-coin, t-ring, t-badge, t-dot) on the part that should move.
D=lambda p:f'''<defs><linearGradient id="{p}r" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ff5a60"/><stop offset=".55" stop-color="#E01119"/><stop offset="1" stop-color="#8f0a10"/></linearGradient><linearGradient id="{p}rs" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b30d14"/><stop offset="1" stop-color="#5c0509"/></linearGradient><linearGradient id="{p}w" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff"/><stop offset="1" stop-color="#d9d9de"/></linearGradient><linearGradient id="{p}ws" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#c4c4cc"/><stop offset="1" stop-color="#8d8d97"/></linearGradient><linearGradient id="{p}gl" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".7"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient><radialGradient id="{p}sh" cx=".5" cy=".5" r=".5"><stop offset="0" stop-color="#000" stop-opacity=".55"/><stop offset="1" stop-color="#000" stop-opacity="0"/></radialGradient><linearGradient id="{p}g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6ff2a1"/><stop offset="1" stop-color="#16a34a"/></linearGradient></defs>'''
SPEED=f'''<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">{D('k')}<ellipse cx="32" cy="58" rx="17" ry="3" fill="url(#ksh)"/><rect x="28" y="6" width="8" height="7" rx="2" fill="url(#kws)"/><rect x="28" y="4" width="8" height="6" rx="2" fill="url(#kw)"/><circle cx="32" cy="35" r="19" fill="url(#krs)" transform="translate(0 3)"/><circle cx="32" cy="35" r="19" fill="url(#kr)"/><path d="M19 27a15 15 0 0 1 22-7" stroke="url(#kgl)" stroke-width="4" fill="none" stroke-linecap="round" opacity=".8"/><circle cx="32" cy="35" r="12.5" fill="url(#kw)"/><g class="t-spin"><path d="M32 35V26.5" stroke="#8f0a10" stroke-width="3.4" stroke-linecap="round"/><path d="M32 35l6 4" stroke="#E01119" stroke-width="3.4" stroke-linecap="round"/></g><circle cx="32" cy="35" r="2.4" fill="#5c0509"/><path d="M49 12l3 3" stroke="url(#kws)" stroke-width="4" stroke-linecap="round"/></svg>'''
COST=f'''<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">{D('c')}<ellipse cx="32" cy="58" rx="20" ry="3" fill="url(#csh)"/><g transform="translate(0 2)"><ellipse cx="25" cy="47" rx="15" ry="5.5" fill="url(#cws)"/><rect x="10" y="41" width="30" height="6" fill="url(#cws)"/><ellipse cx="25" cy="41" rx="15" ry="5.5" fill="url(#cw)"/><ellipse cx="25" cy="39" rx="15" ry="5.5" fill="url(#cws)"/><rect x="10" y="33" width="30" height="6" fill="url(#cws)"/><ellipse cx="25" cy="33" rx="15" ry="5.5" fill="url(#cw)"/></g><g class="t-coin"><circle cx="41" cy="25" r="15" fill="url(#crs)" transform="translate(0 3)"/><circle cx="41" cy="25" r="15" fill="url(#cr)"/><path d="M31 19a11 11 0 0 1 14-6" stroke="url(#cgl)" stroke-width="3.5" fill="none" stroke-linecap="round"/><text x="41" y="31.5" text-anchor="middle" font-family="Arial Black,Arial" font-weight="900" font-size="17" fill="#fff">$</text></g></svg>'''
DEMO=f'''<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">{D('d')}<ellipse cx="32" cy="58" rx="19" ry="3" fill="url(#dsh)"/><path d="M20 30h26a7 7 0 0 1 7 7v8a7 7 0 0 1-7 7h-3l-1 6-6-6H20a7 7 0 0 1-7-7v-8a7 7 0 0 1 7-7z" fill="url(#dws)" transform="translate(0 2)"/><path d="M20 30h26a7 7 0 0 1 7 7v8a7 7 0 0 1-7 7h-3l-1 6-6-6H20a7 7 0 0 1-7-7v-8a7 7 0 0 1 7-7z" fill="url(#dw)"/><circle class="t-dot" cx="24" cy="41" r="2.6" fill="#8d8d97"/><circle class="t-dot" cx="33" cy="41" r="2.6" fill="#8d8d97"/><circle class="t-dot" cx="42" cy="41" r="2.6" fill="#8d8d97"/><path d="M14 8h28a7 7 0 0 1 7 7v7a7 7 0 0 1-7 7H22l-6 5 .5-5H14a7 7 0 0 1-7-7v-7a7 7 0 0 1 7-7z" fill="url(#drs)" transform="translate(0 3)"/><path d="M14 8h28a7 7 0 0 1 7 7v7a7 7 0 0 1-7 7H22l-6 5 .5-5H14a7 7 0 0 1-7-7v-7a7 7 0 0 1 7-7z" fill="url(#dr)"/><path d="M12 13a6 6 0 0 1 5-3h20" stroke="url(#dgl)" stroke-width="3" fill="none" stroke-linecap="round"/><path d="M17 19h20M17 24h12" stroke="#fff" stroke-width="3" stroke-linecap="round"/></svg>'''
MISS=f'''<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64">{D('m')}<ellipse cx="30" cy="58" rx="18" ry="3" fill="url(#msh)"/><g class="t-ring"><g transform="translate(4 12) scale(2.1)"><path d="M6.6 10.8c1.4 2.8 3.8 5.1 6.6 6.6l2.2-2.2c.3-.3.7-.4 1-.2 1.1.4 2.3.6 3.6.6.6 0 1 .4 1 1V20c0 .6-.4 1-1 1-9.4 0-17-7.6-17-17 0-.6.4-1 1-1h3.5c.6 0 1 .4 1 1 0 1.3.2 2.5.6 3.6.1.3 0 .7-.2 1l-2.3 2.2z" fill="url(#mrs)" transform="translate(0 1.4)"/><path d="M6.6 10.8c1.4 2.8 3.8 5.1 6.6 6.6l2.2-2.2c.3-.3.7-.4 1-.2 1.1.4 2.3.6 3.6.6.6 0 1 .4 1 1V20c0 .6-.4 1-1 1-9.4 0-17-7.6-17-17 0-.6.4-1 1-1h3.5c.6 0 1 .4 1 1 0 1.3.2 2.5.6 3.6.1.3 0 .7-.2 1l-2.3 2.2z" fill="url(#mr)"/></g></g><path d="M14 22c1-4 3-6.5 6-8" stroke="url(#mgl)" stroke-width="3" fill="none" stroke-linecap="round"/><g class="t-badge"><circle cx="46" cy="17" r="10" fill="url(#mws)" transform="translate(0 2)"/><circle cx="46" cy="17" r="10" fill="url(#mw)"/><path d="M42 13l8 8M50 13l-8 8" stroke="#E01119" stroke-width="3.2" stroke-linecap="round"/></g></svg>'''

ICONS = {'speed-to-lead-calculator/': SPEED, 'ai-receptionist-cost-calculator/': COST,
         'missed-call-calculator/': MISS, '../demo/': DEMO}
